function O({registerIndicator:C,sourceValues:L,nulls:R}){C({id:"oa-roofing",name:"Ehlers Roofing Filter (ROOFING)",category:"Filters",placement:"pane",inputs:[{key:"hpLength",type:"number",label:"HP Length",default:48,min:1,max:5e3,step:1,tooltip:"Highpass cutoff period: removes cycles longer than this"},{key:"ssLength",type:"number",label:"SS Length",default:10,min:1,max:5e3,step:1,tooltip:"Super Smoother cutoff period: removes cycles shorter than this"},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"roofing",type:"line",title:"Roofing",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",dashed:!0}],calc(o,c){const S=Math.max(1,Math.floor(Number(c.hpLength)||48)),v=Math.max(1,Math.floor(Number(c.ssLength)||10)),e=L(o,c.source??"close"),a=Math.sqrt(2)*Math.PI,p=a/S,i=Math.exp(-p),f=2*i*Math.cos(p),u=-i*i,w=(1+f-u)/4,g=a/v,l=Math.exp(-g),m=2*l*Math.cos(g),y=-l*l,A=1-m-y,n=new Array(o.length).fill(0),h=new Array(o.length).fill(0),N=new Array(o.length).fill(NaN);for(let t=0;t<o.length;t++){const b=e[t],d=t>=1?e[t-1]:NaN,M=Number.isFinite(b)?b:Number.isFinite(d)?d:0,x=t>=1&&Number.isFinite(e[t-1])?e[t-1]:M,k=t>=2&&Number.isFinite(e[t-2])?e[t-2]:x,P=t>=1?n[t-1]:0,E=t>=2?n[t-2]:0;let s=w*(M-2*x+k)+f*P+u*E;Number.isFinite(s)||(s=0),n[t]=s;const F=t>=1?n[t-1]:s,I=t>=1?h[t-1]:F,H=t>=2?h[t-2]:F;let r=A*s+m*I+y*H;Number.isFinite(r)||(r=0),h[t]=r,N[t]=r}return{roofing:R(N)}}})}export{O as default};
